import csv
import io


def rows(text):
    """Yield each CSV record after the header, per standard CSV rules."""
    reader = csv.reader(io.StringIO(text, newline=''))
    for index, record in enumerate(reader):
        if index == 0:
            continue  # header
        yield [field.strip() for field in record]

